        content: `<h2>مشروع أرسنال مع أرتيتا: كيف أعاد المدرب بناء الهوية التكتيكية للفريق؟</h2>

<p>
يُعد مشروع أرسنال تحت قيادة ميكيل أرتيتا من أبرز المشاريع التكتيكية التي تطورت بشكل واضح خلال السنوات الأخيرة. الفكرة لم تكن مجرد تغيير طريقة اللعب أو التعاقد مع لاعبين جدد، بل بناء هوية متكاملة تعتمد على السيطرة، التنظيم، الضغط، جودة الاستحواذ، إدارة المساحات، والعمل الجماعي في مختلف مراحل المباراة.
</p>

<p>
ومع مرور الوقت، أصبح أرسنال أكثر قدرة على تغيير شكله وفقاً للمنافس وسيناريو المباراة. وفي موسم 2025/26 ظهر هذا التطور بشكل واضح، بعدما أصبح الفريق أكثر مرونة بين 4-3-3 و4-2-3-1، مع قدرة أكبر على تعديل طريقة اللعب أثناء المباريات. كما توج الفريق موسمه بإحراز لقب الدوري الإنجليزي الممتاز للمرة الأولى منذ 22 عاماً. :contentReference[oaicite:0]{index=0}
</p>

<h3>من بناء فريق إلى بناء هوية</h3>

<p>
عندما نتحدث عن مشروع أرتيتا، فإن أهم عنصر ليس الرسم التكتيكي وحده، لأن 4-3-3 أو 4-2-3-1 مجرد نقطة بداية. الأهم هو الطريقة التي يتحرك بها اللاعبون داخل هذه الرسومات، والمساحات التي يبحثون عنها، وكيفية انتقال الفريق من الدفاع إلى الهجوم والعكس.
</p>

<p>
الفكرة الأساسية أصبحت مرتبطة بالتحكم في المباراة. عندما يمتلك أرسنال الكرة، يحاول خلق زوايا تمرير متعددة، وتحريك دفاع الخصم، والحفاظ على توازن يمنع المنافس من استغلال فقدان الكرة بسهولة.
</p>

<p>
وعندما يخسر الكرة، لا يتحول الفريق مباشرة إلى مجموعة من اللاعبين المتراجعين، بل يحاول استعادة الكرة بسرعة أو على الأقل إغلاق المساحات التي يستطيع الخصم استخدامها في الانتقال.
</p>

<h3>4-3-3 كنقطة انطلاق</h3>

<p>
كان 4-3-3 من أكثر الأشكال ارتباطاً بأرسنال خلال مراحل مهمة من مشروع أرتيتا. هذا الرسم يمنح الفريق ثلاث وحدات واضحة: خط دفاع، محور أو لاعب ارتكاز، ولاعبا وسط متقدمان، إضافة إلى الأجنحة والمهاجم.
</p>

<p>
لكن الشكل الحقيقي أثناء الاستحواذ يمكن أن يتغير بشكل كبير. فقد يتحول أحد الظهيرين إلى الداخل، بينما يبقى الآخر واسعاً، أو يتحرك أحد لاعبي الوسط إلى منطقة أعلى، في حين يتراجع لاعب آخر لتأمين البناء.
</p>

<p>
لهذا السبب لا يمكن تحليل أرسنال من خلال الأرقام الموجودة على ورقة التشكيلة فقط. الحركة بعد بداية المباراة هي التي تكشف الخطة الحقيقية.
</p>

<h3>التحول نحو 4-2-3-1</h3>

<p>
من أهم مظاهر تطور مشروع أرتيتا زيادة استخدام 4-2-3-1. وفي موسم 2025/26 بدأ أرسنال 14 مباراة في الدوري بهذا الشكل، مقارنة بمباراتين فقط في الموسم السابق، بينما بدأ 24 مباراة بـ4-3-3. هذا التغيير منح المدرب خيارات أكبر للتعامل مع اختلاف الخصوم وتوفر اللاعبين. :contentReference[oaicite:1]{index=1}
</p>

<p>
وجود ثنائي في العمق يمكن أن يمنح الفريق حماية أكبر أمام خط الدفاع، وفي الوقت نفسه يسمح للاعب رقم 10 بالتحرك في مناطق متقدمة بين خطوط المنافس.
</p>

<p>
كما يمكن لهذا الشكل أن يكون مفيداً في الضغط، لأن المهاجم ولاعب الوسط المتقدم يستطيعان توجيه بناء المنافس نحو جهة معينة، بينما يتحرك لاعبو الوسط والخط الخلفي لإغلاق الخيارات الأخرى.
</p>

<h3>بناء اللعب من الخلف</h3>

<p>
أحد أهم ملامح كرة القدم التي يريدها أرتيتا هو أن يبدأ الهجوم من الحارس والمدافعين، وليس بمجرد إرسال الكرة إلى الأمام.
</p>

<p>
الحارس يصبح لاعباً إضافياً في مرحلة البناء، والمدافعون يحاولون جذب ضغط المنافس قبل البحث عن التمريرة المناسبة. الهدف ليس الاستحواذ من أجل الاستحواذ، بل استخدام الكرة لتحريك الخصم وخلق مساحة جديدة.
</p>

<p>
عندما يتقدم مهاجم أو لاعب وسط من المنافس للضغط، يمكن أن تظهر مساحة خلفه. وإذا تحرك لاعب آخر في الوقت المناسب إلى هذه المنطقة، تصبح التمريرة التالية أكثر قيمة.
</p>

<p>
هذه العملية تتطلب من اللاعبين الهدوء، والقدرة على قراءة الضغط، وفهم المكان الذي يجب أن تكون فيه الكرة بعد التمريرة الحالية.
</p>

<h3>دور الحارس في المشروع</h3>

<p>
الحارس الحديث في منظومة أرتيتا ليس مجرد لاعب ينتظر التسديدات. عليه أن يكون جزءاً من عملية بناء اللعب، وأن يعرف متى يحتفظ بالكرة ومتى يمررها، ومتى يستخدم التمرير القصير ومتى يلجأ إلى الكرة الطويلة.
</p>

<p>
وجود حارس قادر على المشاركة في البناء يسمح للفريق بالحصول على لاعب إضافي عند مواجهة الضغط العالي، لكنه في الوقت نفسه يتطلب تركيزاً كبيراً لأن فقدان الكرة في هذه المنطقة قد يكون خطيراً.
</p>

<h3>الظهير ليس مجرد ظهير</h3>

<p>
من أهم أسرار كرة القدم الحديثة تغير وظيفة الظهير. ففي بعض المواقف يمكن أن يبقى اللاعب على الخط لمنح الفريق العرض، وفي مواقف أخرى يدخل إلى الوسط ليصنع زيادة عددية.
</p>

<p>
هذه المرونة تساعد أرسنال على التحكم في وسط الملعب دون خسارة العرض على الأطراف.
</p>

<p>
كما أن الظهير يمكن أن يتحرك إلى الأمام في اللحظة التي يستلم فيها الجناح الكرة، ما يسمح بصناعة مواقف اثنين ضد واحد أمام المدافع المنافس.
</p>

<p>
لكن هذه التحركات تحتاج إلى توازن، لأن تقدم الظهير يترك مساحة خلفه. ولهذا يجب أن يكون هناك لاعب آخر مستعد لتغطية المنطقة في حالة فقدان الكرة.
</p>

<h3>العرض والعمق</h3>

<p>
أرسنال لا يعتمد على اللعب في وسط الملعب فقط. العرض عنصر أساسي في محاولة تفكيك الدفاعات المتكتلة.
</p>

<p>
عندما يبقى الجناح قريباً من الخط، يضطر الظهير المنافس إلى اتخاذ قرار: هل يبقى قريباً من الجناح أم يدخل لمساعدة زملائه في الوسط؟
</p>

<p>
أي قرار يمكن أن يفتح مساحة. إذا بقي الظهير واسعاً، يمكن أن تظهر مساحة بين الخطوط. وإذا دخل إلى الداخل، تصبح المساحة على الجناح أكثر وضوحاً.
</p>

<p>
وهنا تظهر أهمية التوقيت، لأن المساحة لا تكون مفيدة إلا إذا استغلها اللاعب في اللحظة المناسبة.
</p>

<h3>مارتن أوديغارد وصناعة المساحات</h3>

<p>
دور لاعب الوسط المتقدم في مشروع أرتيتا لا يرتبط فقط بالتمرير الأخير. اللاعب يحتاج إلى التحرك لاستقبال الكرة، ثم استخدام موقعه لجذب لاعب من دفاع المنافس.
</p>

<p>
وجود لاعب قادر على الاستلام بين الخطوط يجعل دفاع المنافس أمام مشكلة مستمرة: هل يخرج المدافع لمراقبته أم يبقى في الخط الخلفي؟
</p>

<p>
إذا خرج المدافع، يمكن أن تظهر مساحة خلفه. وإذا بقي في مكانه، يمكن للاعب المستلم أن يستدير أو يمرر إلى لاعب آخر.
</p>

<p>
وهذا النوع من القرارات هو الذي يجعل التحركات بدون كرة بنفس أهمية التمريرة نفسها.

<h3>ديكلان رايس وتطور دور الوسط</h3>

<p>
أحد الأمثلة المهمة على المرونة التكتيكية هو استخدام ديكلان رايس في أدوار مختلفة. لم يعد دوره محصوراً في استعادة الكرة، بل أصبح قادراً على المشاركة في البناء، التقدم بالكرة، تغطية المساحات، ودعم الهجوم عند الحاجة.
</p>

<p>
وفي بعض مباريات موسم 2025/26 استخدم أرتيتا رايس في دور أعمق إلى جانب مارتن زوبيميندي، ما أعطى الفريق ثنائية في محور الوسط. :contentReference[oaicite:2]{index=2}
</p>

<p>
هذا النوع من المرونة يسمح لأرسنال بتغيير طريقة بناء اللعب دون الحاجة دائماً إلى تغيير اللاعبين.
</p>

<h3>الضغط العالي</h3>

<p>
الضغط في أرسنال ليس مجرد الركض خلف حامل الكرة. الفكرة الأساسية هي الضغط كفريق واحد.
</p>

<p>
يمكن للمهاجم أن يبدأ الضغط على قلب الدفاع، بينما يغلق الجناح خيار التمرير نحو الظهير، ويتقدم لاعب الوسط لتغطية لاعب المنافس في العمق.
</p>

<p>
بهذه الطريقة يصبح الهدف هو إجبار المنافس على اتخاذ قرار سيئ، وليس فقط محاولة افتكاك الكرة فوراً.
</p>

<p>
وأظهرت تحليلات UEFA أن ضغط أرسنال أمام باريس سان جيرمان كان منظماً بشكل واضح، حيث حاول الفريق توجيه بناء المنافس نحو جهة محددة ثم زيادة الضغط هناك بشكل جماعي. :contentReference[oaicite:3]{index=3}
</p>

<h3>الضغط بعد فقدان الكرة</h3>

<p>
بعد فقدان الكرة، تكون الثواني الأولى حاسمة. إذا كان اللاعبون قريبين من بعضهم، يستطيع أرسنال محاولة استعادة الكرة قبل أن يبدأ الخصم هجمته.
</p>

<p>
أما إذا كانت المسافات كبيرة، يصبح الضغط أكثر صعوبة، ولذلك يرتبط الضغط الجيد دائماً بالتنظيم أثناء الاستحواذ.
</p>

<p>
هذه العلاقة بين الهجوم والدفاع من أهم عناصر كرة القدم الحديثة: طريقة بناء الهجمة يجب أن تساعد الفريق أيضاً على الدفاع إذا فقد الكرة.
</p>

<h3>الدفاع بالمساحات</h3>

<p>
الدفاع عند أرسنال لا يعتمد فقط على مراقبة اللاعبين. التحكم في المساحات جزء أساسي من المنظومة.
</p>

<p>
المدافعون يحتاجون إلى معرفة متى يتقدمون، ومتى يتراجعون، ومتى يخرج قلب الدفاع من مكانه لمواجهة لاعب يستلم بين الخطوط.
</p>

<p>
وجود لاعبين قادرين على الدفاع في المساحات الواسعة يصبح مهماً جداً، خصوصاً عندما يكون الخط الخلفي متقدماً.
</p>

<p>
وفي هذه الحالة يصبح التواصل بين قلبَي الدفاع، الظهير، ولاعب الوسط ضرورياً لتجنب ظهور فراغات بين الخطوط.
</p>

<h3>أرسنال والكتلة الدفاعية المنخفضة</h3>

<p>
أحد أصعب الاختبارات لأي فريق يريد المنافسة على الألقاب هو مواجهة الخصوم الذين يتراجعون إلى الخلف.
</p>

<p>
عندما يغلق المنافس المساحات أمام منطقة الجزاء، تصبح المساحات بين الخطوط قليلة، ويحتاج الفريق إلى تحريك الكرة بسرعة أكبر وتغيير جهة اللعب باستمرار.
</p>

<p>
أرسنال يحاول في هذه الحالات استخدام العرض، التحركات المتبادلة، الكرات العرضية، الاختراقات من العمق، والتسديدات عندما تتاح المساحة.
</p>

<p>
كما أصبحت الكرات الثابتة جزءاً مهماً من الحل، خصوصاً عندما يكون من الصعب اختراق دفاع منظم باللعب المفتوح.
</p>

<h3>الكرات الثابتة كسلاح تكتيكي</h3>

<p>
النجاح في الكرات الثابتة لم يعد تفصيلاً ثانوياً في مشروع أرسنال. وجود المدرب المتخصص نيكولاس جوفر ساعد على تحويل الركلات الركنية والمواقف الثابتة إلى جزء واضح من الهوية الهجومية للفريق. :contentReference[oaicite:4]{index=4}
</p>

<p>
الفكرة لا تتعلق فقط بقوة الضربة أو دقة الإرسال، بل بالحركة الجماعية، حجب المدافعين، تغيير أماكن الانطلاق، واستغلال نقاط ضعف طريقة دفاع المنافس.
</p>

<p>
وفي دوري أبطال أوروبا 2025/26 ظهرت هذه القوة مرة أخرى، إذ أشارت تحليلات UEFA إلى قدرة أرسنال على استغلال الكرات الثابتة ضد دفاعات منظمة، مع استخدام حركات جماعية لخلق المساحات داخل منطقة الجزاء. :contentReference[oaicite:5]{index=5}
</p>

<p>
أما في الدوري الإنجليزي الممتاز 2025/26، فسجل أرسنال 19 هدفاً من الركلات الركنية، وهو رقم قياسي في تاريخ المسابقة، كما استقبل سبعة أهداف فقط من الكرات الثابتة طوال الموسم. :contentReference[oaicite:6]{index=6}
</p>

<h3>التحولات الهجومية</h3>

<p>
رغم ارتباط أرسنال بالاستحواذ، فإن الفريق لا يحتاج دائماً إلى بناء الهجمة ببطء.
</p>

<p>
عندما يستعيد الكرة في منطقة متقدمة، يمكن أن يتحول مباشرة إلى الهجوم، خصوصاً إذا كان المنافس غير منظم بعد فقدان الكرة.
</p>

<p>
السرعة هنا لا تعني إرسال الكرة إلى الأمام بشكل عشوائي، بل اتخاذ القرار المناسب قبل أن يستعيد الخصم تنظيمه الدفاعي.
</p>

<h3>التحولات الدفاعية</h3>

<p>
في المقابل، يعتبر منع الهجمات المرتدة من أهم التحديات التي تواجه أي فريق يستحوذ كثيراً.
</p>

<p>
لهذا يحتاج أرسنال إلى ما يسمى بالتوازن الدفاعي أثناء الهجوم. بعض اللاعبين يتقدمون للمشاركة، بينما يبقى آخرون في مواقع تسمح بإيقاف التحول إذا ضاعت الكرة.
</p>

<p>
هذا التوازن هو الذي يمنح الفريق القدرة على الهجوم بعدد كبير من اللاعبين دون أن يصبح مكشوفاً بشكل كامل.
</p>

<h3>دور قلبَي الدفاع</h3>

<p>
قلب الدفاع في منظومة أرتيتا يحتاج إلى أكثر من القوة في المواجهات الفردية. عليه أن يكون قادراً على الدفاع أمام مساحة كبيرة، قراءة الكرات خلف الخط، والمشاركة في بناء اللعب.
</p>

<p>
كما أن تقدم قلب الدفاع أحياناً إلى مناطق أعلى من الملعب يمكن أن يصنع زيادة عددية ويساعد الفريق على كسر ضغط المنافس.
</p>

<p>
لكن هذا النوع من الحرية لا يمكن أن يحدث دون وجود تغطية مناسبة خلف اللاعب.
</p>

<h3>سرعة القرار أهم من سرعة اللاعب فقط</h3>

<p>
كرة القدم الحديثة تعتمد بشكل كبير على سرعة التفكير. اللاعب قد يكون سريعاً بدنياً، لكن إذا تأخر في اتخاذ القرار فلن يستفيد من سرعته.
</p>

<p>
أرسنال يحاول بناء فريق يستطيع اتخاذ القرارات بسرعة: متى يمرر؟ متى يحتفظ بالكرة؟ متى يهاجم المساحة؟ ومتى يتراجع؟
</p>

<p>
لهذا أصبحت التدريبات التكتيكية مرتبطة بالقرارات وليس فقط بالمهارات الفردية.
</p>

<h3>التنوع الهجومي</h3>

<p>
من أهم مظاهر تطور المشروع أن أرسنال لم يعد يعتمد على طريقة واحدة لصناعة الفرص.
</p>

<p>
يمكن أن تأتي الخطورة من الجناحين، من التحركات بين الخطوط، من الكرات العرضية، من الاختراقات، من التسديد، أو من الكرات الثابتة.
</p>

<p>
هذا التنوع يجعل مهمة المنافس أكثر صعوبة، لأنه لا يستطيع التركيز على مصدر واحد فقط لإيقاف الفريق.
</p>

<h3>إدارة نتيجة المباراة</h3>

<p>
من علامات الفرق التي تنافس على البطولات قدرتها على إدارة المباراة بعد تسجيل الهدف الأول.
</p>

<p>
في موسم 2025/26، حقق أرسنال الفوز في 24 من أصل 27 مباراة في الدوري سجل فيها أولاً، وخسر مباراة واحدة فقط في تلك الحالات. هذا يعكس قدرة واضحة على التحكم في المباريات بعد التقدم. :contentReference[oaicite:7]{index=7}
</p>

<p>
إدارة النتيجة لا تعني دائماً التراجع. أحياناً تعني الاحتفاظ بالكرة، وأحياناً رفع الضغط، وأحياناً تقليل المخاطرة في مناطق معينة.
</p>

<p>
وهنا تظهر أهمية قراءة المباراة، لأن نفس الخطة لا يمكن أن تكون مناسبة لكل دقيقة وكل نتيجة.
</p>

<h3>التكيف مع الخصم</h3>

<p>
من أبرز التحولات في مشروع أرتيتا أن المرونة أصبحت أكبر. لم يعد الهدف هو فرض شكل واحد مهما كان الخصم.
</p>

<p>
يمكن تغيير عدد لاعبي الوسط، طريقة الضغط، مواقع الأجنحة، مستوى الخط الدفاعي أو طريقة البناء بناءً على خصائص المنافس.
</p>

<p>
هذا النوع من التكيف ظهر بشكل واضح في موسم 2025/26، عندما أصبح أرتيتا أكثر استعداداً لاستخدام تشكيلات مختلفة من مباراة إلى أخرى. :contentReference[oaicite:8]{index=8}
</p>

<h3>الجانب النفسي</h3>

<p>
التكتيك وحده لا يكفي للفوز بالبطولات. الفريق يحتاج إلى شخصية تحافظ على التركيز عندما تتغير ظروف المباراة.
</p>

<p>
قد يتقدم الفريق بهدف، وقد يتلقى هدفاً، وقد يواجه ضغطاً جماهيرياً أو مباراة كبيرة، وفي كل حالة يحتاج اللاعبون إلى المحافظة على المبادئ الأساسية دون فقدان المرونة.
</p>

<p>
هذه الشخصية لا تظهر في الإحصائيات وحدها، بل في طريقة تعامل الفريق مع اللحظات الصعبة.
</p>

<h3>دور دكة البدلاء</h3>

<p>
كلما ارتفع مستوى المنافسة، أصبحت دكة البدلاء جزءاً من الخطة وليس مجرد احتياط.
</p>

<p>
البديل قد يدخل لتغيير الضغط، زيادة السرعة، إضافة لاعب بين الخطوط أو حماية النتيجة.
</p>

<p>
وهذا يعني أن أرتيتا يحتاج إلى لاعبين قادرين على فهم أكثر من دور تكتيكي، لأن المباراة قد تتطلب تغييراً في الشكل دون تغيير الفكرة الأساسية.
</p>

<h3>البيانات والتحليل</h3>

<p>
كرة القدم الحديثة أصبحت مرتبطة بشكل كبير بتحليل الفيديو والبيانات. المدرب لا يكتفي بمشاهدة المباراة، بل يبحث عن الأنماط المتكررة: أين يفقد الفريق الكرة؟ أين يصنع الفرص؟ كيف يدافع الخصم عن الكرات الثابتة؟ وأي منطقة يمكن استغلالها؟
</p>

<p>
البيانات لا تعطي القرار وحدها، لكنها تساعد الجهاز الفني على فهم التفاصيل التي قد لا تكون واضحة خلال المشاهدة العادية.
</p>

<h3>منظومة متكاملة وليست مجموعة نجوم</h3>

<p>
نجاح مشروع أرسنال لا يمكن اختزاله في لاعب واحد. الفكرة الأساسية هي أن كل لاعب يؤدي وظيفة تخدم المنظومة.
</p>

<p>
الجناح يحتاج إلى الظهير، والظهير يحتاج إلى لاعب الوسط الذي يغطي خلفه، ولاعب الوسط يحتاج إلى قلب الدفاع، والمهاجم يحتاج إلى التحركات التي يقوم بها زملاؤه لفتح المساحات.
</p>

<p>
كلما كانت هذه العلاقات واضحة، أصبح الفريق أكثر قدرة على تنفيذ أفكاره تحت الضغط.
</p>

<h3>لماذا أصبح المشروع أكثر نضجاً؟</h3>

<p>
المرحلة الأولى من أي مشروع تدريبي تكون غالباً مرتبطة ببناء الأساس: تحديد طريقة اللعب، تطوير اللاعبين، تحسين التنظيم، وتثبيت المبادئ.
</p>

<p>
بعد ذلك تأتي مرحلة أكثر تعقيداً: معرفة متى يجب تغيير هذه المبادئ وكيفية استخدامها ضد أنواع مختلفة من الخصوم.
</p>

<p>
وهذا هو التطور الذي يمكن ملاحظته في أرسنال. الفريق لم يتخل عن هويته، لكنه أصبح أكثر قدرة على تغيير تفاصيلها.
</p>

<h3>الدروس التي يمكن أن تتعلمها الأندية المغربية</h3>

<p>
مشروع أرتيتا يقدم مجموعة من الدروس المهمة للأندية المغربية، خصوصاً فيما يتعلق ببناء الهوية قبل البحث عن النتائج السريعة.
</p>

<p>
أولاً، يجب أن تكون هناك فلسفة واضحة في جميع الفئات العمرية. ثانياً، يجب تطوير اللاعبين القادرين على أداء أكثر من وظيفة. ثالثاً، يجب الاستثمار في التحليل والتكوين البدني والتكتيكي.
</p>

<p>
كما أن الكرات الثابتة توضح أن التفاصيل الصغيرة يمكن أن تتحول إلى مصدر كبير للنتائج عندما يتم التعامل معها بجدية وتدريب متخصص.
</p>

<h3>المستقبل: الهوية مع المزيد من المرونة</h3>

<p>
التحدي أمام أرتيتا ليس فقط الحفاظ على المستوى، بل الاستمرار في تطوير الفريق مع تغير المنافسين.
</p>

<p>
عندما تصبح طريقة لعب معينة معروفة للجميع، يبدأ الخصوم في البحث عن حلول لإيقافها. لذلك يحتاج الفريق إلى التطور باستمرار دون فقدان هويته.
</p>

<p>
وهنا يمكن أن يكون التنوع التكتيكي مهماً جداً: 4-3-3 عندما يحتاج الفريق إلى توزيع معين، 4-2-3-1 عندما يكون وجود لاعب متقدم بين الخطوط أكثر فائدة، وضغط مختلف حسب طريقة بناء الخصم.
</p>

<h3>الخلاصة</h3>

<p>
مشروع أرسنال مع ميكيل أرتيتا يمثل مثالاً واضحاً على أن بناء فريق كبير يحتاج إلى أكثر من التعاقد مع لاعبين جيدين. هناك حاجة إلى هوية، تنظيم، تدريب، تحليل، صبر، وتطوير مستمر.
</p>

<p>
الفريق أصبح أكثر نضجاً في الاستحواذ، الضغط، التحولات، الدفاع، الكرات الثابتة وإدارة نتائج المباريات. والأهم أن المرونة التكتيكية أصبحت جزءاً من المشروع، بعدما كان 4-3-3 يمثل الشكل الأكثر ثباتاً في مراحل سابقة.
</p>

<p>
وفي موسم 2025/26 وصل المشروع إلى محطة تاريخية بإحراز أرسنال لقب الدوري الإنجليزي الممتاز بعد 22 عاماً من الانتظار، مع موسم أظهر فيه الفريق قدرة أكبر على التكيف وإدارة المباريات واستغلال التفاصيل الصغيرة. :contentReference[oaicite:9]{index=9}
</p>

<p>
لهذا فإن قصة أرسنال تحت أرتيتا ليست فقط قصة مدرب غيّر طريقة لعب فريق، بل تجربة في كيفية تحويل مجموعة من اللاعبين إلى منظومة لها شخصية واضحة، قادرة على المنافسة والتطور من موسم إلى آخر.
</p>`
